package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Derives the {@code locality} (canonical region) from an owner's city using a fixed
 * city-to-region table. Cities not in the table resolve to {@code UNKNOWN}.
 */
public final class Locality {

    private static final Map<String, String> CITY_REGION =
            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    private Locality() {
    }

    public static String of(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.CityAtCapacityException;

/**
 * Rejects a create-owner request whose city already holds {@value #CAPACITY} or more owners,
 * before {@link BuildOwner} runs. Cities are compared exactly, as elsewhere in the pipeline.
 */
public class RequireCityCapacity {

    static final int CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws CityAtCapacityException {
        String city = request.getCity();
        long count = ownerRepository.findAll().stream()
            .filter(existing -> city.equals(existing.getCity()))
            .count();
        if (count >= CAPACITY) {
            throw new CityAtCapacityException(city);
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.Map;

/**
 * Canonical form of a street address: trim and collapse internal whitespace, upper-case,
 * and expand common abbreviations (ST->STREET, RD->ROAD, AVE->AVENUE) as whole words.
 * Returns {@code ""} for a null or all-whitespace input, so a blank address is rejected
 * by the required-field check. Idempotent, so it can be reapplied wherever addresses are
 * compared.
 */
public final class NormaliseAddress {

    private static final Map<String, String> ABBREVIATIONS =
            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private NormaliseAddress() {
    }

    public static String normalise(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
        if (collapsed.isEmpty()) {
            return "";
        }
        StringBuilder sb = new StringBuilder(collapsed.length());
        for (String token : collapsed.split(" ")) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(token, token));
        }
        return sb.toString();
    }
}

